-- Bell, Book and Candle
DELETE FROM projectTags WHERE projectId = (SELECT id FROM projects WHERE slug = 'bell-book-and-candle');
INSERT INTO projectTags (projectId, tagId)
SELECT p.id, t.id FROM projects p CROSS JOIN tags t
WHERE p.slug = 'bell-book-and-candle'
AND t.name IN ('Mid-Century Modern', 'Realistic Interior', '1950s', 'Summer Stock', '2025', 'Comedy');

